//! Generated from the font's file type table. Do not edit by hand.

use super::{Glyph, Tone};

pub(super) const FILE: Glyph = Glyph { char: '\u{ea7b}', tone: Tone::Secondary }; // file
pub(super) const RULES: Glyph = Glyph { char: '\u{f39e}', tone: Tone::Secondary }; // logo-filled
pub(super) const VSCODE: Glyph = Glyph { char: '\u{f51a}', tone: Tone::Blue }; // file-type-vsc-filled
pub(super) const ENV: Glyph = Glyph { char: '\u{f393}', tone: Tone::Secondary }; // cog-filled
pub(super) const PLAN: Glyph = Glyph { char: '\u{edd0}', tone: Tone::Yellow }; // list-todo

/// The agent rules files, by lower-case name.
pub(super) fn is_rules_file(name: &str) -> bool {
    matches!(name, ".cursorignore" | ".cursorindexingignore" | ".cursorrules")
}

/// The VS Code settings files marked inside `.vscode`, by lower-case name.
pub(super) fn is_vscode_file(name: &str) -> bool {
    matches!(name, "settings.json" | "launch.json" | "tasks.json" | "extensions.json")
}

